INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist visuelles Feedback nur für die Ästhetik wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Es bestätigt Nutzeraktionen"}, {"text": "Ja", "correct": false, "because": "Funktionalität steht im Vordergrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit strukturierter Navigation?', 3, '[{"text": "Nutzerführung", "correct": true, "because": "Erleichtert Orientierung"}, {"text": "Maximale Farbvielfalt", "correct": false, "because": "Nicht relevant"}, {"text": "Code-Optimierung", "correct": false, "because": "Technische Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente verbessern die visuelle Hierarchie?', 5, '[{"text": "Größenunterschiede", "correct": true, "because": "Hebt Wichtiges hervor"}, {"text": "Kontrastreiche Farben", "correct": true, "because": "Lenkt Aufmerksamkeit"}, {"text": "Datenbankzugriff", "correct": false, "because": "Nicht visuell"}, {"text": "Serverantwortzeit", "correct": false, "because": "Technisch, nicht gestalterisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Feedback erhöht die Benutzerfreundlichkeit. b) Hierarchie ist nur für Designer wichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hierarchie hilft allen Nutzern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Gestaltung von visuellem Feedback?', 4, '[{"text": "Klarheit der Rückmeldung", "correct": false, "because": "Kernmerkmal"}, {"text": "Reaktionsgeschwindigkeit", "correct": false, "because": "Wichtig für Nutzer"}, {"text": "Hardware-Spezifikationen", "correct": true, "because": "Nicht direkt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine klare Hierarchie die Navigation erleichtert?', 2, '[{"text": "Ja", "correct": true, "because": "Struktur führt den Nutzer"}, {"text": "Nein", "correct": false, "because": "Hierarchie ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Mittel nutze ich für sofortiges visuelles Feedback?', 3, '[{"text": "Animationen", "correct": true, "because": "Zeigt Aktionen direkt an"}, {"text": "Statische Bilder", "correct": false, "because": "Keine Reaktion"}, {"text": "Datenbankabfragen", "correct": false, "because": "Technisch, nicht visuell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze verbessern die strukturierte Navigation?', 5, '[{"text": "Breadcrumbs", "correct": true, "because": "Zeigt den Pfad"}, {"text": "Klar definierte Menüs", "correct": true, "because": "Erleichtert Zugriff"}, {"text": "Maximale Farben", "correct": false, "because": "Ästhetisch, nicht funktional"}, {"text": "Code-Komplexität", "correct": false, "because": "Technische Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Visuelles Feedback reduziert Fehler. b) Hierarchie ist nur für große Seiten nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hierarchie hilft überall"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine gute visuelle Rückmeldung?', 4, '[{"text": "Konsistenz", "correct": false, "because": "Wichtig für Verständnis"}, {"text": "Deutliche Signale", "correct": false, "because": "Bestätigt Aktionen"}, {"text": "Datenbankstruktur", "correct": true, "because": "Nicht visuell relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Feedback nur für interaktive Elemente nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Statusanzeigen nützlich"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden stärken die visuelle Hierarchie?', 4, '[{"text": "Abstände", "correct": true, "because": "Trennt Inhalte"}, {"text": "Schriftgrößen", "correct": true, "because": "Hebt Prioritäten hervor"}, {"text": "Backend-Logik", "correct": false, "because": "Nicht gestalterisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Navigation ohne Hierarchie funktioniert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Struktur ist essenziell"}, {"text": "Ja", "correct": false, "because": "Ohne Hierarchie chaotisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Navigation einer App?', 3, '[{"text": "Klarheit", "correct": true, "because": "Nutzer müssen sich orientieren"}, {"text": "Farbenvielfalt", "correct": false, "because": "Sekundär"}, {"text": "Serverantwort", "correct": false, "because": "Technisch, nicht gestalterisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Feedback zeigt Nutzeraktionen an. b) Hierarchie ist nur optisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hierarchie ist funktional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Mittel nutze ich für effektives Feedback?', 5, '[{"text": "Farbänderungen", "correct": true, "because": "Zeigt Statuswechsel"}, {"text": "Pop-ups", "correct": true, "because": "Direkte Rückmeldung"}, {"text": "Datenbankabfragen", "correct": false, "because": "Technisch, nicht visuell"}, {"text": "Hohe Latenz", "correct": false, "because": "Verzögert Feedback"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Hierarchie für eine Website unwichtig?', 3, '[{"text": "Inhaltsanordnung", "correct": false, "because": "Definiert Prioritäten"}, {"text": "Leserichtung", "correct": false, "because": "Leitet den Blick"}, {"text": "Code-Struktur", "correct": true, "because": "Technisch, nicht gestalterisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit Feedback? Ist es immer visuell?', 3, '[{"text": "Nein", "correct": true, "because": "Kann auch akustisch sein"}, {"text": "Ja", "correct": false, "because": "Andere Formen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Navigation ohne Feedback funktioniert?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzer brauchen Bestätigung"}, {"text": "Ja", "correct": false, "because": "Ohne Feedback verwirrend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für eine klare Navigation?', 4, '[{"text": "Menüleiste", "correct": true, "because": "Bietet strukturierte Optionen"}, {"text": "Zufällige Buttons", "correct": false, "because": "Verwirrend"}, {"text": "Leere Flächen", "correct": false, "because": "Kein Nutzen"}]');
